### Fixed RTL
module traffic_fsm (
    input logic clk,
    input logic rst,
    input logic tick,
    output logic green,
    output logic red
);
    typedef enum logic {S0, S1} state_t;
    state_t state, next_state;

    always_ff @(posedge clk or posedge rst) begin
        if (rst)
            state <= S0;
        else
            state <= next_state;
    end

    always_comb begin
        next_state = state;
        case (state)
            S0: if (tick) next_state = S1;
            S1: if (tick) next_state = S0;
        endcase
    end

    always_comb begin
        green = 0;
        red = 0;
        case (state)
            S0: green = 1;
            S1: red = 1;
        endcase
    end
endmodule

### Bug Explanation
The FSM gets stuck in state S1 because the next-state logic sends S1 back to itself when tick is high. That breaks the intended toggle behaviour. The fix changes the transition from S1 so the machine returns to S0 on the next tick.

### Verification Suggestion
After reset, apply several tick pulses and confirm the FSM alternates between S0 and S1. Also, verify the green and red outputs match the active state.

